use super::fault::*;
use super::{AuthTokenError, CallingError, HandlingError};
use crate::call::RawCallError;
#[cfg(feature = "storage")]
use crate::storage::*;
use crate::sys::{SysErr, SyscallErrorCode, SyscallNo};
use crate::xdr::*;
use core::error::Error;
use core::fmt::{self, Display};
#[cfg(feature = "debugging")]
use thiserror::Error;
#[cfg(feature = "spec")]
use xdrs::XDR;

/// An exception generated by SDK internals.
///
#[derive(Debug, Clone, PartialEq, ReadXDR, WriteXDR)]
#[cfg_attr(feature = "debugging", derive(Error))]
#[groundhog_macros::exn(version = "1.0.0")]
#[repr(i32)]
#[non_exhaustive]
pub enum LibraryExn {
    #[cfg_attr(feature = "debugging", error(transparent))]
    Syscall(SyscallExn),

    #[cfg_attr(feature = "debugging", error("Handling a contract call: {0}"))]
    Handling(HandlingError),

    #[cfg_attr(feature = "debugging", error("Making a contract call: {0}"))]
    Calling(CallingError),

    #[cfg_attr(feature = "debugging", error("Called contract reverted: {0}"))]
    Called(#[cfg_attr(feature = "debugging", source)] FaultString),

    #[cfg_attr(feature = "debugging", error("Encoding auth token: {0}"))]
    AuthToken(AuthTokenError),

    #[cfg_attr(
        feature = "debugging",
        error("bytestring_get_sized: expected {expected}, found {found}")
    )]
    BytestringWrongSize { expected: u32, found: u32 },

    #[cfg_attr(feature = "debugging", error("non-negative int went negative"))]
    NonNegativeIntUnderflow,

    #[cfg_attr(feature = "debugging", error("non-negative int overflow"))]
    NonNegativeIntOverflow,

    #[cfg(feature = "storage")]
    #[cfg_attr(feature = "debugging", error("Storage error: {0}"))]
    Storage(StorageError),
}

impl From<HandlingError> for LibraryExn {
    fn from(e: HandlingError) -> Self {
        Self::Handling(e)
    }
}

impl From<CallingError> for LibraryExn {
    fn from(e: CallingError) -> Self {
        Self::Calling(e)
    }
}

impl From<AuthTokenError> for LibraryExn {
    fn from(e: AuthTokenError) -> Self {
        Self::AuthToken(e)
    }
}

#[cfg(feature = "storage")]
impl From<StorageError> for LibraryExn {
    fn from(e: StorageError) -> Self {
        Self::Storage(e)
    }
}

impl LibraryExn {
    pub fn as_syscall_exn(&self) -> Option<&SyscallExn> {
        if let LibraryExn::Syscall(se) = self {
            Some(se)
        } else {
            None
        }
    }
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn library_throw<E: Into<LibraryExn> + core::fmt::Debug>(e: E) -> ! {
    let exn = crate::exn::cross_exn::ContractExn::new(e.into());
    crate::contract_abort_encoded(&exn)
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn client_library_throw<E: Into<LibraryExn> + core::fmt::Debug>(e: E) -> ! {
    let exn = crate::exn::cross_exn::ContractExn::new(e.into());
    crate::client_contract_abort_encoded(&exn)
}

/// Throw an exception because a syscall produced an error.
///
#[cfg_attr(feature = "debugging", track_caller)]
pub fn syscall_throw(callno: SyscallNo, errno: SysErr) -> ! {
    library_throw(syscall_exn(callno, errno))
}

pub fn syscall_exn(callno: SyscallNo, errno: SysErr) -> LibraryExn {
    LibraryExn::Syscall(SyscallExn::new(callno, errno))
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn nnint_overflow() -> ! {
    library_throw(LibraryExn::NonNegativeIntOverflow)
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn nnint_underflow() -> ! {
    library_throw(LibraryExn::NonNegativeIntUnderflow)
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn decoding_args_throw(e: &RawCallError) -> ! {
    library_throw(HandlingError::DecodingArgs(FaultString::from_display(e)))
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn encoding_success_throw<E: Error>(e: E) -> ! {
    library_throw(HandlingError::EncodingSuccess(FaultString::from_display(e)))
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn encoding_exception_throw<E: Error>(e: E) -> ! {
    library_throw(HandlingError::EncodingException(FaultString::from_display(
        e,
    )))
}

#[cfg_attr(feature = "debugging", track_caller)]
pub fn encoding_event_throw<E: Display>(e: E) -> ! {
    library_throw(HandlingError::EncodingEvent(FaultString::from_display(e)))
}

#[derive(Debug, Clone, Copy, ReadXDR, WriteXDR, PartialEq)]
#[cfg_attr(feature = "debugging", derive(Error))]
#[cfg_attr(feature = "spec", derive(XDR))]
pub struct SyscallExn {
    callno: SyscallNo,
    errno: SysErr,
}

impl SyscallExn {
    pub fn new(callno: SyscallNo, errno: SysErr) -> Self {
        Self { callno, errno }
    }

    pub fn callno(&self) -> SyscallNo {
        self.callno
    }

    pub fn has_code(&self, err_code: SyscallErrorCode) -> bool {
        self.errno.is_code(err_code)
    }

    pub fn is(&self, call_no: SyscallNo, err_code: SyscallErrorCode) -> bool {
        self.callno == call_no && self.errno == err_code.into()
    }
}

impl Display for SyscallExn {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Syscall {:?} failed with {}", self.callno, self.errno)
    }
}

#[cfg(test)]
mod selector_tests {
    use super::*;
    use crate::exn::Exn;

    #[test]
    fn library_exn_selector_matches_sha256() {
        let expected = groundhog_contract_util::exception_selector(
            "1.0.0",
            env!("CARGO_PKG_NAME"),
            "LibraryExn",
        );
        assert_eq!(LibraryExn::SELECTOR, expected);
    }

    #[test]
    fn library_exn_selector_nonzero() {
        assert_ne!(LibraryExn::SELECTOR, 0);
    }
}
